import{_ as a,o as t,c as n,a3 as s}from"./chunks/framework.SG7_9Yi6.js";const u=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/concepts.md","filePath":"explanation/concepts.md"}'),o={name:"explanation/concepts.md"};function r(i,e,d,c,h,l){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>The domain vocabulary, each term defined once. For the wire shapes themselves see <a href="./../reference/">Reference</a>.</p><h2 id="campaign" tabindex="-1">Campaign <a class="header-anchor" href="#campaign" aria-label="Permalink to &quot;Campaign&quot;">​</a></h2><p>A declarative workflow: a YAML graph of nodes (drivers, expressions, subworkflows) plus ingress routes that map events onto it. Campaigns are entities — <code>kind=&quot;campaign&quot;</code> — with <code>campaign.start|pause| resume|cancel|signal</code> ops, and <code>campaign serve</code> can host many of them behind one webhook listener.</p><h2 id="node-hub" tabindex="-1">Node / hub <a class="header-anchor" href="#node-hub" aria-label="Permalink to &quot;Node / hub&quot;">​</a></h2><p>A <strong>node</strong> (<code>peregrin-node</code>, <code>peregrin serve</code>) is the per-machine daemon: it owns the session plane (via <code>sepia serve</code>) and the campaign engine, and serves the <code>/api/*</code> surface. The <strong>hub</strong> (<code>peregrin-hub</code>) is a thin <code>hypha-hub</code> gateway that merges every configured node&#39;s entity/session views into one API and arbitrates locks and fleet dispatch.</p><h2 id="entity" tabindex="-1">Entity <a class="header-anchor" href="#entity" aria-label="Permalink to &quot;Entity&quot;">​</a></h2><p>The substrate&#39;s unit of state: <code>{id, kind, indexDoc}</code> plus namespaced ops and opaque snapshots. Peregrin registers its kinds — <code>sepia-session</code>, <code>campaign</code> — on the generic entity plane; it never names a sepia type in substrate code.</p><h2 id="plane" tabindex="-1">Plane <a class="header-anchor" href="#plane" aria-label="Permalink to &quot;Plane&quot;">​</a></h2><p>A capability surface with its own routes and ownership: the session plane (sepia mechanism), the entity plane (generic substrate), the integration planes (peregrin&#39;s sessions-as-entities, campaigns), and the app plane (<code>peregrin-http</code> composing one listener, the hub gateway). See <a href="./architecture.html#planes">Architecture</a>.</p><h2 id="driver" tabindex="-1">Driver <a class="header-anchor" href="#driver" aria-label="Permalink to &quot;Driver&quot;">​</a></h2><p>A node type that does work: <code>agent</code>, <code>shell</code>, <code>git</code>, <code>schedule</code>, <code>github-webhook</code>, <code>sturn</code>, <code>subworkflow</code>, and friends. Drivers are registered in one unified registry and declared in campaign YAML — the full list and contracts are in <a href="./drivers.html">Drivers</a> and the <a href="./../reference/cli.html">CLI reference</a>.</p><h2 id="event" tabindex="-1">Event <a class="header-anchor" href="#event" aria-label="Permalink to &quot;Event&quot;">​</a></h2><p>The unit of flow: named payloads matched by <code>on:</code> patterns that wake campaign nodes. Events are also state — see <a href="./events.html">Events</a> and the <a href="./event-graph-model.html">event graph model</a>.</p><h2 id="bundle" tabindex="-1">Bundle <a class="header-anchor" href="#bundle" aria-label="Permalink to &quot;Bundle&quot;">​</a></h2><p>A tamias package of type <code>peregrin-bundle</code>: a <code>main.yaml</code> campaign plus a <code>provider</code> manifest declaring services and ingress. Installed and deployed through tamias, never by peregrin itself — see <a href="./../how-to/run-the-docs-deploy-bundle.html">Run the docs-deploy bundle</a>.</p><h2 id="capability-secret-grant" tabindex="-1">Capability / secret grant <a class="header-anchor" href="#capability-secret-grant" aria-label="Permalink to &quot;Capability / secret grant&quot;">​</a></h2><p><code>capabilities:</code> on a campaign bounds what its drivers may do; <code>capabilities.secrets</code> names exactly which secret names the ingress/status drivers may resolve. A name that doesn&#39;t resolve fails the node rather than silently degrading — see <a href="./safety.html">Safety</a>.</p><h2 id="run-supersede" tabindex="-1">Run / supersede <a class="header-anchor" href="#run-supersede" aria-label="Permalink to &quot;Run / supersede&quot;">​</a></h2><p>A <strong>run</strong> is one execution of a campaign. The queue policy is latest-wins: a newer event on the same <code>{repo}:{ref}</code> key cancels the in-flight run (<code>cancelled</code>/superseded) — see <a href="./../reference/queue-supersede.html">Queue &amp; supersede</a>.</p>',20)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
